INSERT IGNORE INTO materiales(sku,nombre,descripcion,especificacion,unidad,categoria_id) SELECT v.sku,v.nombre,v.nombre,CONCAT(v.size_in,' pulgadas - deck'), 'unidad',c.id FROM (SELECT 'SK8-VIOLET-80' sku,'Violet Current' nombre,'8.0' size_in UNION ALL SELECT 'SK8-MINT-825','Mint Theory','8.25' UNION ALL SELECT 'SK8-EMBER-80','Ember Lines','8.0' UNION ALL SELECT 'SK8-POLAR-825','Polar Bloom','8.25' UNION ALL SELECT 'SK8-COBALT-80','Cobalt Echo','8.0' UNION ALL SELECT 'SK8-SOLAR-825','Solar Type','8.25' UNION ALL SELECT 'SK8-INK-80','Ink Ritual','8.0' UNION ALL SELECT 'SK8-PEACH-825','Peach Radio','8.25' UNION ALL SELECT 'SK8-LIME-80','Lime Shift','8.0' UNION ALL SELECT 'SK8-ROYAL-825','Royal Noise','8.25' UNION ALL SELECT 'SK8-SAND-80','Sand Signal','8.0' UNION ALL SELECT 'SK8-RED-825','Red Frequency','8.25') v JOIN categorias c ON c.nombre='Skateboards demo';
INSERT IGNORE INTO store_products(slug,name,description,product_type,collection_name,featured) VALUES ('violet-current','Violet Current','Corrientes violetas y una composición fluida para una tabla que se siente rápida.','DECK','Archivo gráfico 03',FALSE),('mint-theory','Mint Theory','Verde menta, geometría y contraste para una sesión limpia.','DECK','Archivo gráfico 03',FALSE),('ember-lines','Ember Lines','Líneas de brasa sobre fondo oscuro con una actitud directa.','DECK','Archivo gráfico 03',FALSE),('polar-bloom','Polar Bloom','Flores frías y color blanco para una gráfica luminosa.','DECK','Archivo gráfico 03',FALSE),('cobalt-echo','Cobalt Echo','Azul cobalto y ondas repetidas con estética sonora.','DECK','Archivo gráfico 03',FALSE),('solar-type','Solar Type','Tipografía solar y amarillo intenso para llamar la atención.','DECK','Archivo gráfico 03',FALSE),('ink-ritual','Ink Ritual','Tinta negra y gestos manuales para una tabla sobria.','DECK','Archivo gráfico 03',FALSE),('peach-radio','Peach Radio','Durazno, señales y un toque retro para la calle.','DECK','Archivo gráfico 03',FALSE),('lime-shift','Lime Shift','Verde lima y movimiento diagonal para una configuración viva.','DECK','Archivo gráfico 03',FALSE),('royal-noise','Royal Noise','Ruido gráfico en tonos reales y una lectura contundente.','DECK','Archivo gráfico 03',FALSE),('sand-signal','Sand Signal','Arena y señalética minimalista para rodar todos los días.','DECK','Archivo gráfico 03',FALSE),('red-frequency','Red Frequency','Frecuencia roja con alto contraste y personalidad.','DECK','Archivo gráfico 03',FALSE);
INSERT IGNORE INTO store_variants(product_id,material_id,sku,size_in,sale_price_crc,low_stock_threshold,specs_json) SELECT p.id,m.id,m.sku,v.size_in,v.price,2,JSON_OBJECT('material','Arce canadiense','ancho',v.size_in,'tipo','Deck') FROM (SELECT 'violet-current' slug,'SK8-VIOLET-80' sku,'8.0' size_in,29700 price UNION ALL SELECT 'mint-theory','SK8-MINT-825','8.25',31200 UNION ALL SELECT 'ember-lines','SK8-EMBER-80','8.0',28700 UNION ALL SELECT 'polar-bloom','SK8-POLAR-825','8.25',31800 UNION ALL SELECT 'cobalt-echo','SK8-COBALT-80','8.0',30100 UNION ALL SELECT 'solar-type','SK8-SOLAR-825','8.25',32700 UNION ALL SELECT 'ink-ritual','SK8-INK-80','8.0',29300 UNION ALL SELECT 'peach-radio','SK8-PEACH-825','8.25',30600 UNION ALL SELECT 'lime-shift','SK8-LIME-80','8.0',29900 UNION ALL SELECT 'royal-noise','SK8-ROYAL-825','8.25',32100 UNION ALL SELECT 'sand-signal','SK8-SAND-80','8.0',28200 UNION ALL SELECT 'red-frequency','SK8-RED-825','8.25',30900) v JOIN store_products p ON p.slug=v.slug JOIN materiales m ON m.sku=v.sku;
INSERT IGNORE INTO movimientos_stock(material_id,cantidad,tipo,ubicacion_destino_id,documento,motivo,idempotency_key) SELECT m.id,6,'APERTURA',u.id,'SKATE-DEMO-CATALOG-03','Existencia ficticia de demostracion',CONCAT('seed-skate-opening-03-',m.sku) FROM materiales m JOIN ubicaciones u ON u.codigo='BOD-CENTRAL' WHERE m.sku IN('SK8-VIOLET-80','SK8-MINT-825','SK8-EMBER-80','SK8-POLAR-825','SK8-COBALT-80','SK8-SOLAR-825','SK8-INK-80','SK8-PEACH-825','SK8-LIME-80','SK8-ROYAL-825','SK8-SAND-80','SK8-RED-825');
